'use strict';

// MODULES //

var arraylikefcn = require( '@stdlib/assert/tools/array-like-function' );
var isLineStyle = require( '@stdlib/plot/base/assert/is-line-style' );


// MAIN //

/**
* Tests whether an input value is an array of line styles.
*
* @name isLineStyleArray
* @type {Function}
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an array of line styles
*
* @example
* var bool = isLineStyleArray( [ '-' ] );
* // returns true
*
* bool = isLineStyleArray( {} );
* // returns false
*
* bool = isLineStyleArray( 'foo' );
* // returns false
*/
var isLineStyleArray = arraylikefcn( isLineStyle );


// EXPORTS //

module.exports = isLineStyleArray;
